import Combine
import Foundation

enum DockScreenState: Equatable, Sendable {
    case configurationError(String)
    case idle([DockHostViewModel])
    case loading([DockHostViewModel])
    case loaded(DockRenderSnapshot)
}

@MainActor
final class DockScreenStore: ObservableObject {
    @Published private(set) var state: DockScreenState
    @Published private(set) var options: DockProjectionOptions
    @Published private(set) var searchText: String
    @Published private(set) var actionError: String?

    private let coalescer: RenderCoalescer<DockRenderSnapshot>
    private let now: @Sendable () -> Date
    private var renderTask: Task<Void, Never>?
    private var searchDebounceTask: Task<Void, Never>?
    private var latestRevision = RenderRevision.zero

    init(
        hosts: [DockHostViewModel],
        options: DockProjectionOptions = DockProjectionOptions(),
        coalescer: RenderCoalescer<DockRenderSnapshot> = RenderCoalescer<DockRenderSnapshot>(),
        now: @escaping @Sendable () -> Date = Date.init
    ) {
        self.state = .idle(hosts)
        self.options = options
        self.searchText = options.searchText
        self.coalescer = coalescer
        self.now = now
        self.actionError = nil
    }

    init(configurationError message: String) {
        self.state = .configurationError(message)
        self.options = DockProjectionOptions()
        self.searchText = ""
        self.coalescer = RenderCoalescer<DockRenderSnapshot>()
        self.now = Date.init
        self.actionError = nil
    }

    deinit {
        renderTask?.cancel()
        searchDebounceTask?.cancel()
    }

    func start() {
        guard renderTask == nil else {
            return
        }

        renderTask = Task { [weak self, coalescer] in
            let stream = await coalescer.stream()
            for await renderSnapshot in stream {
                let publishStartedAt = Date()
                await MainActor.run {
                    self?.state = .loaded(renderSnapshot)
                    PerformanceProbe.event(
                        "dock.main_publish",
                        fields: [
                            "revision": "\(renderSnapshot.revision.rawValue)",
                            "rows": "\(renderSnapshot.snapshot.rows.count)",
                            "visible_rows": "\(renderSnapshot.projection.rows.count)",
                            "groups": "\(renderSnapshot.projection.groups.count)",
                            "pinned_rows": "\(renderSnapshot.projection.pinnedRows.count)",
                            "hosts": "\(renderSnapshot.snapshot.hosts.count)",
                            "duration_ms": "\(PerformanceProbe.milliseconds(since: publishStartedAt))",
                        ]
                    )
                }
            }
        }
    }

    func stop() {
        renderTask?.cancel()
        renderTask = nil
        searchDebounceTask?.cancel()
        searchDebounceTask = nil
    }

    func setLoading(hosts: [DockHostViewModel]) {
        state = .loading(hosts)
    }

    func setIdle(hosts: [DockHostViewModel]) {
        state = .idle(hosts)
    }

    func setConfigurationError(_ message: String) {
        state = .configurationError(message)
    }

    func setActionError(_ message: String?) {
        actionError = message
    }

    func setLens(_ lens: DockLensID) {
        updateOptions(
            DockProjectionOptions(
                lens: lens,
                searchText: searchText,
                filters: options.filters
            ),
            syncSearchText: false
        )
    }

    func setSearchText(_ searchText: String) {
        self.searchText = searchText
        searchDebounceTask?.cancel()
        searchDebounceTask = Task { [weak self] in
            do {
                try await Task.sleep(
                    for: .milliseconds(CodexDockConstants.Rendering.searchDebounceMilliseconds)
                )
            } catch {
                return
            }
            await MainActor.run {
                self?.applySearchText(searchText)
            }
        }
    }

    private func applySearchText(_ searchText: String) {
        searchDebounceTask = nil
        updateOptions(
            DockProjectionOptions(
                lens: options.lens,
                searchText: searchText,
                filters: options.filters
            )
        )
    }

    func setFilters(_ filters: DockFilterState) {
        updateOptions(
            DockProjectionOptions(
                lens: options.lens,
                searchText: searchText,
                filters: filters
            ),
            syncSearchText: false
        )
    }

    func updateOptions(_ options: DockProjectionOptions, syncSearchText: Bool = true) {
        self.options = options
        if syncSearchText {
            searchText = options.searchText
        }
        guard case .loaded(let renderSnapshot) = state else {
            return
        }
        enqueueProjection(snapshot: renderSnapshot.snapshot)
    }

    func publish(snapshot: DockSnapshot) {
        enqueueProjection(snapshot: snapshot)
    }

    private func enqueueProjection(snapshot: DockSnapshot) {
        latestRevision = latestRevision.next()
        let revision = latestRevision
        let options = self.options
        let now = self.now
        let coalescer = self.coalescer
        let queuedAt = Date()
        PerformanceProbe.event(
            "dock.render.enqueue",
            fields: [
                "revision": "\(revision.rawValue)",
                "rows": "\(snapshot.rows.count)",
                "hosts": "\(snapshot.hosts.count)",
                "lens": options.lens.rawValue,
                "search": options.searchText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? "false" : "true",
                "filters": "\(options.filters.activeFilterCount)",
                "partial": "\(snapshot.isPartial)",
            ]
        )
        if snapshot.rows.count > CodexDockConstants.Rendering.maxDockRowsPerMainPublish {
            DockLog.rendering.warning("dock render input exceeds main publish row budget rows=\(snapshot.rows.count, privacy: .public) budget=\(CodexDockConstants.Rendering.maxDockRowsPerMainPublish, privacy: .public)")
        }

        Task.detached(priority: .userInitiated) {
            let signpostState = DockSignpost.rendering.beginInterval(RenderSignpostName.dockRenderProject)
            defer {
                DockSignpost.rendering.endInterval(RenderSignpostName.dockRenderProject, signpostState)
            }
            let renderStartedAt = Date()
            let renderSnapshot = DockRenderProjector(now: now).render(
                snapshot: snapshot,
                options: options,
                revision: revision
            )
            PerformanceProbe.event(
                "dock.render.detached_finished",
                fields: [
                    "revision": "\(revision.rawValue)",
                    "rows": "\(snapshot.rows.count)",
                    "queue_delay_ms": "\(PerformanceProbe.milliseconds(since: queuedAt, now: renderStartedAt))",
                    "render_ms": "\(PerformanceProbe.milliseconds(since: renderStartedAt))",
                ]
            )
            await coalescer.submit(renderSnapshot, revision: revision)
        }
    }
}

import SwiftUI

#if os(iOS)
import UIKit
#elseif os(macOS)
import AppKit
#endif

public struct CodexDockRootView: View {
    @Environment(\.scenePhase) private var scenePhase
    @StateObject private var dockStore: DockStore
    @StateObject private var archiveStore: ArchiveStore
    @StateObject private var archiveCleanupStore: ArchiveCleanupStore
    @StateObject private var hostsStore: HostSettingsStore
    @StateObject private var connectivityStore: AppConnectivityStore
    @StateObject private var connectivityScreenStore: ConnectivityScreenStore
    @StateObject private var lifecycleCoordinator: AppLifecycleCoordinator
    private let runtime: ClientRuntime?
    private let usesRuntimeConnectivitySink: Bool
    private let threadDetailFactory: any ThreadDetailSessionMaking
    @State private var foregroundResumeTask: Task<Void, Never>?
    @State private var activeTaskSheet: DockTaskSheet?

    public init(store: DockStore) {
        self.threadDetailFactory = AppServerThreadDetailSessionFactory()
        _dockStore = StateObject(wrappedValue: store)
        if let host = store.hostConfiguration,
           let registry = try? HostRegistry(hosts: [host]) {
            let runtime = ClientRuntime(registry: registry)
            self.runtime = runtime
            self.usesRuntimeConnectivitySink = false
            _archiveStore = StateObject(wrappedValue: ArchiveStore(registry: registry))
            _archiveCleanupStore = StateObject(wrappedValue: ArchiveCleanupStore(registry: registry, cardStateProvider: store))
            _hostsStore = StateObject(wrappedValue: HostSettingsStore(registry: registry))
            _connectivityStore = StateObject(wrappedValue: AppConnectivityStore(registry: registry))
            _connectivityScreenStore = StateObject(
                wrappedValue: runtime.makeConnectivityScreenStore()
            )
        } else {
            self.runtime = nil
            self.usesRuntimeConnectivitySink = false
            let error = DockHostConfigurationError.missingEndpoint
            _archiveStore = StateObject(wrappedValue: ArchiveStore(configurationError: error))
            _archiveCleanupStore = StateObject(wrappedValue: ArchiveCleanupStore(configurationError: error))
            _hostsStore = StateObject(wrappedValue: HostSettingsStore(configurationError: error))
            _connectivityStore = StateObject(wrappedValue: AppConnectivityStore(configurationError: error))
            _connectivityScreenStore = StateObject(
                wrappedValue: ConnectivityScreenStore(configurationError: error)
            )
        }
        _lifecycleCoordinator = StateObject(wrappedValue: AppLifecycleCoordinator())
    }

    public init(
        registry: HostRegistry,
        client: AppServerThreadCommandClient = AppServerThreadCommandClient(),
        streamClient: any ThreadCardStreamConnecting = AppServerThreadCardStreamClient(),
        threadDetailFactory: any ThreadDetailSessionMaking = AppServerThreadDetailSessionFactory(),
        metadataStore: any LocalThreadMetadataStoring = FileLocalThreadMetadataStore(),
        lifecycleCoordinator: AppLifecycleCoordinator = AppLifecycleCoordinator(),
        connectivityStore: AppConnectivityStore? = nil,
        now: @escaping @Sendable () -> Date = Date.init
    ) {
        self.init(
            runtime: ClientRuntime(registry: registry, now: now),
            client: client,
            streamClient: streamClient,
            threadDetailFactory: threadDetailFactory,
            metadataStore: metadataStore,
            lifecycleCoordinator: lifecycleCoordinator,
            connectivityStore: connectivityStore
        )
    }

    public init(
        runtime: ClientRuntime,
        client: AppServerThreadCommandClient = AppServerThreadCommandClient(),
        streamClient: any ThreadCardStreamConnecting = AppServerThreadCardStreamClient(),
        threadDetailFactory: any ThreadDetailSessionMaking = AppServerThreadDetailSessionFactory(),
        metadataStore: any LocalThreadMetadataStoring = FileLocalThreadMetadataStore(),
        lifecycleCoordinator: AppLifecycleCoordinator = AppLifecycleCoordinator(),
        connectivityStore: AppConnectivityStore? = nil
    ) {
        let registry = runtime.registry
        self.runtime = runtime
        self.usesRuntimeConnectivitySink = true
        self.threadDetailFactory = threadDetailFactory
        let connectivityStore = connectivityStore ?? AppConnectivityStore(registry: registry, now: runtime.currentDate)
        let dockStore = runtime.makeDockStore(
            streamClient: streamClient,
            archiver: client,
            renamer: client,
            metadataStore: metadataStore
        )
        _dockStore = StateObject(
            wrappedValue: dockStore
        )
        _archiveStore = StateObject(
            wrappedValue: runtime.makeArchiveStore(
                streamClient: AppServerThreadCardStreamClient(view: .archive),
                archiver: client,
                metadataStore: metadataStore
            )
        )
        _archiveCleanupStore = StateObject(
            wrappedValue: ArchiveCleanupStore(
                registry: registry,
                cardStateProvider: dockStore,
                archiver: client,
                now: runtime.currentDate
            )
        )
        _hostsStore = StateObject(
            wrappedValue: runtime.makeHostSettingsStore()
        )
        _connectivityStore = StateObject(wrappedValue: connectivityStore)
        _connectivityScreenStore = StateObject(wrappedValue: runtime.makeConnectivityScreenStore())
        _lifecycleCoordinator = StateObject(wrappedValue: lifecycleCoordinator)
    }

    public init(configurationError error: Error) {
        self.runtime = nil
        self.usesRuntimeConnectivitySink = false
        self.threadDetailFactory = AppServerThreadDetailSessionFactory()
        _dockStore = StateObject(wrappedValue: DockStore(configurationError: error))
        _archiveStore = StateObject(wrappedValue: ArchiveStore(configurationError: error))
        _archiveCleanupStore = StateObject(wrappedValue: ArchiveCleanupStore(configurationError: error))
        _hostsStore = StateObject(wrappedValue: HostSettingsStore(configurationError: error))
        _connectivityStore = StateObject(wrappedValue: AppConnectivityStore(configurationError: error))
        _connectivityScreenStore = StateObject(
            wrappedValue: ConnectivityScreenStore(configurationError: error)
        )
        _lifecycleCoordinator = StateObject(wrappedValue: AppLifecycleCoordinator())
    }

    public var body: some View {
        DockView(
            store: dockStore,
            lifecycleCoordinator: lifecycleCoordinator,
            connectivityReporter: connectivityStore,
            connectivityStore: connectivityStore,
            runtime: runtime,
            threadDetailFactory: threadDetailFactory,
            onOpenArchiveCleanup: {
                activeTaskSheet = .archiveCleanup
            },
            onOpenArchivedThreads: {
                activeTaskSheet = .archivedThreads
            },
            onOpenSystemHealth: {
                activeTaskSheet = .systemHealth
            },
            onOpenRelaySettings: {
                activeTaskSheet = .relaySettings
            },
            onArchiveSucceeded: {
                await archiveStore.refresh()
            }
        )
        .tint(.blue)
        .accessibilityElement(children: .contain)
        .codexAutomationID(AutomationID.App.root)
        .accessibilityValue(activeTaskSheet?.rawValue ?? "dock")
        .sheet(item: $activeTaskSheet) { sheet in
            taskSheet(sheet)
                .dockTaskSheetPresentation()
        }
        .task {
            if usesRuntimeConnectivitySink {
                connectivityScreenStore.start(mirroring: connectivityStore)
            }
            bindConnectivity()
            await runDockRefreshLoop()
        }
        .onChange(of: scenePhase) { _, scenePhase in
            handleScenePhase(scenePhase)
        }
        .onChange(of: hostsStore.registry) { _, registry in
            guard let registry else {
                return
            }
            Task {
                connectivityStore.configure(registry)
                await connectivityScreenStore.configure(registry)
                await dockStore.updateRegistry(registry)
                await archiveStore.updateRegistry(registry)
                await archiveCleanupStore.updateRegistry(registry)
            }
        }
    }

    @ViewBuilder
    private func taskSheet(_ sheet: DockTaskSheet) -> some View {
        switch sheet {
        case .archiveCleanup:
            ArchiveCleanupView(
                store: archiveCleanupStore,
                onOpenArchivedThreads: {
                    activeTaskSheet = .archivedThreads
                },
                onArchiveSucceeded: {
                    await dockStore.refresh()
                    await archiveStore.refresh()
                },
                onClose: {
                    activeTaskSheet = nil
                }
            )
        case .archivedThreads:
            ArchiveView(
                store: archiveStore,
                title: "Archived Threads",
                threadDetailFactory: threadDetailFactory,
                onClose: {
                    activeTaskSheet = nil
                },
                onRestoreSucceeded: {
                    await dockStore.refresh()
                }
            )
        case .systemHealth:
            SystemHealthView(
                store: connectivityStore,
                onOpenRelaySettings: {
                    activeTaskSheet = .relaySettings
                },
                relaySettingsDestination: {
                    HostsView(
                        store: hostsStore,
                        title: "Relay Settings",
                        hidesEditorUntilRequested: true,
                        usesNavigationStack: false
                    )
                },
                onClose: {
                    activeTaskSheet = nil
                }
            )
        case .relaySettings:
            HostsView(
                store: hostsStore,
                title: "Relay Settings",
                hidesEditorUntilRequested: true,
                onClose: {
                    activeTaskSheet = nil
                }
            )
        }
    }

    private func bindConnectivity() {
        guard !usesRuntimeConnectivitySink else {
            return
        }
        dockStore.setConnectivityReporter(connectivityStore)
        archiveStore.setConnectivityReporter(connectivityStore)
        hostsStore.setConnectivityReporter(connectivityStore)
    }

    private func runDockRefreshLoop() async {
        while !Task.isCancelled, !lifecycleCoordinator.allowsForegroundWork {
            do {
                try await Task.sleep(for: CodexDockConstants.AppServer.foregroundPollInterval)
            } catch {
                return
            }
        }

        await dockStore.load()
    }

    private func handleScenePhase(_ scenePhase: ScenePhase) {
        lifecycleCoordinator.handle(appScenePhase(from: scenePhase))
        connectivityStore.reportLifecycle(lifecycleCoordinator.snapshot)

        guard lifecycleCoordinator.snapshot.phase == .foregroundResuming else {
            return
        }

        foregroundResumeTask?.cancel()
        foregroundResumeTask = Task {
            await resumeForegroundWork()
        }
    }

    private func resumeForegroundWork() async {
        guard lifecycleCoordinator.snapshot.phase == .foregroundResuming else {
            return
        }

        await dockStore.refresh()
        await archiveStore.refresh()
        lifecycleCoordinator.finishForegroundResume()
        connectivityStore.reportLifecycle(lifecycleCoordinator.snapshot)
    }

    private func appScenePhase(from scenePhase: ScenePhase) -> AppScenePhase {
        switch scenePhase {
        case .active:
            return .active
        case .inactive:
            return .inactive
        case .background:
            return .background
        @unknown default:
            return .inactive
        }
    }
}

private struct DockScrollOffsetProbe: View {
    var body: some View {
        ZStack {
            GeometryReader { proxy in
                Color.clear
                    .preference(
                        key: DockScrollOffsetPreferenceKey.self,
                        value: proxy.frame(in: .named(DockScrollCoordinateSpace.name)).minY
                    )
            }

            #if os(iOS)
            if PerformanceProbe.isEnabled {
                DockScrollOffsetObserver()
            }
            #endif
        }
        .onPreferenceChange(DockScrollOffsetPreferenceKey.self) { offsetY in
            guard PerformanceProbe.isEnabled else {
                return
            }
            PerformanceProbe.dockSwiftUIScrollOffsetChanged(offsetY: Double(-offsetY))
        }
    }
}

private enum DockScrollCoordinateSpace {
    static let name = "dock-scroll"
}

private struct DockScrollOffsetPreferenceKey: PreferenceKey {
    static let defaultValue: CGFloat = 0

    static func reduce(value: inout CGFloat, nextValue: () -> CGFloat) {
        value = nextValue()
    }
}

#if os(iOS)
private struct DockScrollOffsetObserver: UIViewRepresentable {
    func makeCoordinator() -> Coordinator {
        Coordinator()
    }

    func makeUIView(context: Context) -> UIView {
        let view = ProbeView(frame: .zero)
        view.coordinator = context.coordinator
        DispatchQueue.main.async {
            context.coordinator.attach(from: view)
        }
        return view
    }

    func updateUIView(_ uiView: UIView, context: Context) {
        DispatchQueue.main.async {
            context.coordinator.attach(from: uiView)
        }
    }

    final class ProbeView: UIView {
        weak var coordinator: Coordinator?

        override init(frame: CGRect) {
            super.init(frame: frame)
            isUserInteractionEnabled = false
            isAccessibilityElement = false
        }

        required init?(coder: NSCoder) {
            super.init(coder: coder)
            isUserInteractionEnabled = false
            isAccessibilityElement = false
        }

        override func didMoveToSuperview() {
            super.didMoveToSuperview()
            coordinator?.scheduleAttachmentAttempts(from: self)
        }

        override func didMoveToWindow() {
            super.didMoveToWindow()
            coordinator?.scheduleAttachmentAttempts(from: self)
        }
    }

    @MainActor
    final class Coordinator: NSObject {
        private weak var scrollView: UIScrollView?
        private var observation: NSKeyValueObservation?
        private var attachmentAttempts = 0

        deinit {
            observation?.invalidate()
        }

        func scheduleAttachmentAttempts(from view: UIView) {
            attach(from: view)
            for delay in [0.05, 0.2, 0.6, 1.2, 2.5, 5.0] {
                DispatchQueue.main.asyncAfter(deadline: .now() + delay) { [weak self, weak view] in
                    guard let self, let view else {
                        return
                    }
                    self.attach(from: view)
                }
            }
        }

        func attach(from view: UIView) {
            attachmentAttempts += 1
            guard let scrollView = observedScrollView(for: view),
                  self.scrollView !== scrollView else {
                return
            }
            observation?.invalidate()
            self.scrollView = scrollView
            PerformanceProbe.dockScrollObserverAttached(
                attempt: attachmentAttempts,
                offsetY: Double(scrollView.contentOffset.y),
                contentHeight: Double(scrollView.contentSize.height),
                boundsHeight: Double(scrollView.bounds.height),
                adjustedTopInset: Double(scrollView.adjustedContentInset.top),
                adjustedBottomInset: Double(scrollView.adjustedContentInset.bottom)
            )
            observation = scrollView.observe(\.contentOffset, options: [.new]) { scrollView, _ in
                Task { @MainActor in
                    PerformanceProbe.dockScrollOffsetChanged(
                        offsetY: Double(scrollView.contentOffset.y),
                        contentHeight: Double(scrollView.contentSize.height),
                        boundsHeight: Double(scrollView.bounds.height)
                    )
                }
            }
        }

        private func observedScrollView(for view: UIView) -> UIScrollView? {
            let enclosing = enclosingScrollView(for: view)
            let largestScrollable = view.window.map { window in
                scrollViews(in: window)
                    .filter { isScrollable($0) }
                    .max { lhs, rhs in
                        lhs.contentSize.height < rhs.contentSize.height
                    }
            } ?? nil
            return largestScrollable ?? enclosing
        }

        private func isScrollable(_ scrollView: UIScrollView) -> Bool {
            let scrollableHeight = scrollView.contentSize.height
                + scrollView.adjustedContentInset.top
                + scrollView.adjustedContentInset.bottom
                - scrollView.bounds.height
            return scrollableHeight > 24
        }

        private func enclosingScrollView(for view: UIView) -> UIScrollView? {
            var current = view.superview
            while let candidate = current {
                if let scrollView = candidate as? UIScrollView {
                    return scrollView
                }
                current = candidate.superview
            }
            return nil
        }

        private func scrollViews(in view: UIView) -> [UIScrollView] {
            var matches: [UIScrollView] = []
            if let scrollView = view as? UIScrollView {
                matches.append(scrollView)
            }
            for subview in view.subviews {
                matches.append(contentsOf: scrollViews(in: subview))
            }
            return matches
        }
    }
}
#endif

public struct DockView: View {
    @ObservedObject private var screenStore: DockScreenStore
    private let store: DockStore
    private let lifecycleCoordinator: AppLifecycleCoordinator?
    private let connectivityReporter: (any AppConnectivityReporting)?
    private let connectivityStore: AppConnectivityStore?
    private let runtime: ClientRuntime?
    private let threadDetailFactory: any ThreadDetailSessionMaking
    private let onOpenArchiveCleanup: @MainActor () -> Void
    private let onOpenArchivedThreads: @MainActor () -> Void
    private let onOpenSystemHealth: @MainActor () -> Void
    private let onOpenRelaySettings: @MainActor () -> Void
    private let onArchiveSucceeded: @MainActor () async -> Void
    @State private var isFilterSurfacePresented = false
    @State private var isPinnedCollapsed = false
    @State private var selectedDetailRow: DockRowViewModel?
    @State private var selectedDetailStore: ThreadDetailStore?
    @State private var collapsedHostGroupIDs: Set<String> = []
    @State private var collapsedBranchGroupIDs: Set<String> = []
    @State private var renameDraft: DockRenameDraft?
    @FocusState private var isSearchFocused: Bool

    public init(
        store: DockStore,
        lifecycleCoordinator: AppLifecycleCoordinator? = nil,
        connectivityReporter: (any AppConnectivityReporting)? = nil,
        connectivityStore: AppConnectivityStore? = nil,
        runtime: ClientRuntime? = nil,
        threadDetailFactory: any ThreadDetailSessionMaking = AppServerThreadDetailSessionFactory(),
        onOpenArchiveCleanup: @escaping @MainActor () -> Void = {},
        onOpenArchivedThreads: @escaping @MainActor () -> Void = {},
        onOpenSystemHealth: @escaping @MainActor () -> Void = {},
        onOpenRelaySettings: @escaping @MainActor () -> Void = {},
        onArchiveSucceeded: @escaping @MainActor () async -> Void = {}
    ) {
        self.store = store
        _screenStore = ObservedObject(wrappedValue: store.screenStore)
        self.lifecycleCoordinator = lifecycleCoordinator
        self.connectivityReporter = connectivityReporter
        self.connectivityStore = connectivityStore
        self.runtime = runtime
        self.threadDetailFactory = threadDetailFactory
        self.onOpenArchiveCleanup = onOpenArchiveCleanup
        self.onOpenArchivedThreads = onOpenArchivedThreads
        self.onOpenSystemHealth = onOpenSystemHealth
        self.onOpenRelaySettings = onOpenRelaySettings
        self.onArchiveSucceeded = onArchiveSucceeded
    }

    public var body: some View {
        NavigationStack {
            ScrollView {
                VStack(alignment: .leading, spacing: 18) {
                    DockScrollOffsetProbe()
                        .frame(height: 0)
                        .accessibilityHidden(true)

                    header
                    controls
                    content
                }
                .padding(.horizontal, 16)
                .padding(.top, 14)
                .padding(.bottom, 104)
            }
            .coordinateSpace(name: DockScrollCoordinateSpace.name)
            .background(dockBackgroundColor)
            .dockNavigationChrome()
            .refreshable {
                await store.refresh()
            }
            .navigationDestination(isPresented: detailNavigationBinding) {
                selectedDetailDestination
            }
            .onChange(of: screenStore.state) { _, state in
                syncSelectedDetail(with: state)
                recordLoadedDockViewState(state)
            }
        }
        .sheet(isPresented: $isFilterSurfacePresented) {
            DockFilterSurfaceView(
                filters: filtersBinding,
                projection: currentProjection
            )
        }
        .overlay(alignment: .top) {
            renameOverlay
        }
        .onAppear {
            startPerformanceFrameMonitorIfNeeded()
            recordLoadedDockViewState(screenStore.state)
        }
    }

    @ViewBuilder
    private var renameOverlay: some View {
        if let draft = renameDraft {
            ZStack(alignment: .top) {
                Color.black.opacity(0.18)
                    .ignoresSafeArea()
                    .onTapGesture {
                        dismissRenameDraftWithoutAnimation()
                    }

                DockRenameThreadSheet(
                    draft: draft,
                    isSaving: false,
                    onCancel: {
                        dismissRenameDraftWithoutAnimation()
                    },
                    onSave: { name in
                        saveRename(draft, name: name)
                    }
                )
                .frame(maxWidth: 520)
                .padding(.horizontal, 16)
                .padding(.top, 76)
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .transaction { transaction in
                transaction.disablesAnimations = true
            }
        }
    }

    private var selectedLens: DockLensID {
        screenStore.options.lens
    }

    private var searchText: String {
        screenStore.searchText
    }

    private var filterState: DockFilterState {
        screenStore.options.filters
    }

    private var header: some View {
        VStack(alignment: .leading, spacing: 12) {
            HStack(alignment: .center, spacing: 12) {
