    private func presentRenameSheet(for row: DockRowViewModel) {
        guard store.hostConfiguration(for: row) != nil else {
            return
        }
        DispatchQueue.main.async {
            renameDraft = DockRenameDraft(row: row)
        }
    }

    private func saveRename(_ draft: DockRenameDraft, name: String) -> Bool {
        let trimmedName = name.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmedName.isEmpty else {
            return false
        }
        guard trimmedName != draft.initialName else {
            renameDraft = nil
            return true
        }

        guard store.renameInBackground(draft.row, to: trimmedName) else {
            return false
        }
        dismissRenameDraftWithoutAnimation()
        return true
    }

    private func dismissRenameDraftWithoutAnimation() {
        #if os(iOS)
        UIView.performWithoutAnimation {
            renameDraft = nil
        }
        #else
        var transaction = Transaction(animation: nil)
        transaction.disablesAnimations = true
        withTransaction(transaction) {
            renameDraft = nil
        }
        #endif
    }

    private func syncSelectedDetail(with state: DockScreenState) {
        guard let selectedDetailRow,
              let selectedDetailStore,
              case .loaded(let renderSnapshot) = state,
              let updatedRow = renderSnapshot.snapshot.rows.first(where: { $0.id == selectedDetailRow.id }) else {
            return
        }

        self.selectedDetailRow = updatedRow
        // The Dock stream owns card freshness. Thread Detail uses it only as an
        // invalidation signal, then rereads canonical thread history itself.
        selectedDetailStore.observeDockRowUpdate(updatedRow)
    }

    private func makeThreadDetailStore(
        host: DockHostConfiguration,
        row: DockRowViewModel,
        hostIdentityResolver: DockHostIdentityResolver?
    ) -> ThreadDetailStore {
        if let runtime {
            return runtime.makeThreadDetailStore(
                host: host,
                row: row,
                factory: threadDetailFactory,
                lifecycleCoordinator: lifecycleCoordinator,
                connectivityReporter: connectivityReporter,
                hostIdentityResolver: hostIdentityResolver
            )
        }
        return ThreadDetailStore(
            host: host,
            row: row,
            factory: threadDetailFactory,
            lifecycleCoordinator: lifecycleCoordinator,
            connectivityReporter: connectivityReporter,
            hostIdentityResolver: hostIdentityResolver
        )
    }

