39	private struct DockCardProjectionProjector {
40	    let snapshot: DockSnapshot
41	    let options: DockProjectionOptions
42	
43	    func project() -> DockCardProjection {
44	        let projectStartedAt = Date()
45	        let searchStartedAt = Date()
46	        let searchedRows = snapshot.rows.filter(matchesSearch)
47	        let searchDurationMilliseconds = PerformanceProbe.milliseconds(since: searchStartedAt)
48	        // Idle is a normal status facet. Do not add a second visibility gate.
49	        let filterStartedAt = Date()
50	        let filteredRows = searchedRows.filter(matchesFilters)
51	        let filterDurationMilliseconds = PerformanceProbe.milliseconds(since: filterStartedAt)
52	        let pinnedStartedAt = Date()
53	        let pinnedRows = filteredRows.filter(\.isPinned).sorted(by: pinnedRowPrecedes)
54	        let pinnedDurationMilliseconds = PerformanceProbe.milliseconds(since: pinnedStartedAt)
55	        let bodyStartedAt = Date()
56	        let bodyRows = filteredRows
57	            .filter { !$0.isPinned }
58	            .sorted(by: rowPrecedesByRelayOrder)
59	        let bodyDurationMilliseconds = PerformanceProbe.milliseconds(since: bodyStartedAt)
60	        let visibleStartedAt = Date()
61	        let visibleRows = (pinnedRows + bodyRows).sorted(by: rowPrecedesByRelayOrder)
62	        let visibleDurationMilliseconds = PerformanceProbe.milliseconds(since: visibleStartedAt)
63	        let allPinnedStartedAt = Date()
64	        let allPinnedRows = snapshot.rows.filter(\.isPinned).sorted(by: pinnedRowPrecedes)
65	        let allPinnedDurationMilliseconds = PerformanceProbe.milliseconds(since: allPinnedStartedAt)
66	        let groupsStartedAt = Date()
67	        let groups = groups(for: bodyRows)
68	        let groupsDurationMilliseconds = PerformanceProbe.milliseconds(since: groupsStartedAt)
69	        let emptyReason = visibleRows.isEmpty ? emptyReason(searchedRows: searchedRows) : nil
70	        let summaryStartedAt = Date()
71	        let projectionSummary = summary(for: visibleRows)
72	        let summaryDurationMilliseconds = PerformanceProbe.milliseconds(since: summaryStartedAt)
73	        let facetsStartedAt = Date()
74	        let facets = availableFacets()
75	        let facetsDurationMilliseconds = PerformanceProbe.milliseconds(since: facetsStartedAt)
76	        let checkingHostCount = snapshot.hostStates.filter { $0.status == .checking }.count
77	
78	        let projection = DockCardProjection(
79	            lens: options.lens,
80	            pinnedRows: pinnedRows,
81	            allPinnedRows: allPinnedRows,
82	            pinnedSummary: DockPinnedSummary(
83	                visibleCount: pinnedRows.count,
84	                totalCount: allPinnedRows.count,
85	                hiddenByScopeCount: max(0, allPinnedRows.count - pinnedRows.count)
86	            ),
87	            rows: options.lens == .newest ? bodyRows : [],
88	            groups: groups,
89	            summary: projectionSummary,
90	            availableFacets: facets,
91	            emptyReason: emptyReason,
92	            isPartial: snapshot.isPartial,
93	            checkingHostCount: checkingHostCount
94	        )
95	        if PerformanceProbe.isEnabled {
96	            PerformanceProbe.event(
97	                "dock.card_projection.project",
98	                fields: [
99	                    "rows": "\(snapshot.rows.count)",
100	                    "searched_rows": "\(searchedRows.count)",
101	                    "filtered_rows": "\(filteredRows.count)",
102	                    "body_rows": "\(bodyRows.count)",
103	                    "visible_rows": "\(visibleRows.count)",
104	                    "pinned_rows": "\(pinnedRows.count)",
105	                    "all_pinned_rows": "\(allPinnedRows.count)",
106	                    "groups": "\(groups.count)",
107	                    "hosts": "\(snapshot.hosts.count)",
108	                    "checking_hosts": "\(checkingHostCount)",
109	                    "lens": options.lens.rawValue,
110	                    "search": normalizedQuery(options.searchText).isEmpty ? "false" : "true",
111	                    "filters": "\(options.filters.activeFilterCount)",
112	                    "partial": "\(snapshot.isPartial)",
113	                    "search_ms": "\(searchDurationMilliseconds)",
114	                    "filter_ms": "\(filterDurationMilliseconds)",
115	                    "pinned_ms": "\(pinnedDurationMilliseconds)",
116	                    "body_ms": "\(bodyDurationMilliseconds)",
117	                    "visible_ms": "\(visibleDurationMilliseconds)",
118	                    "all_pinned_ms": "\(allPinnedDurationMilliseconds)",
119	                    "groups_ms": "\(groupsDurationMilliseconds)",
120	                    "summary_ms": "\(summaryDurationMilliseconds)",
121	                    "facets_ms": "\(facetsDurationMilliseconds)",
122	                    "duration_ms": "\(PerformanceProbe.milliseconds(since: projectStartedAt))",
123	                ]
124	            )
125	        }
126	        return projection
127	    }
