142	    private func hostGroups(
143	        for rows: [DockRowViewModel]
144	    ) -> [DockProjectionGroupViewModel] {
145	        let stateByHost = Dictionary(uniqueKeysWithValues: snapshot.hostStates.map { ($0.host.id, $0) })
146	        return snapshot.hosts.compactMap { host in
147	            if !options.filters.selectedHostIDs.isEmpty,
148	               !options.filters.selectedHostIDs.contains(host.id) {
149	                return nil
150	            }
151	
152	            let hostRows = rows
153	                .filter { rowBelongs($0, to: host.id) }
154	                .sorted(by: rowPrecedesByRelayOrder)
155	            let hostState = stateByHost[host.id]
156	            let isUnavailable = hostState?.status.isUnavailable ?? false
157	            guard !hostRows.isEmpty || isUnavailable || hostState?.status == .checking else {
158	                return nil
159	            }
160	
161	            return DockProjectionGroupViewModel(
162	                id: "host::\(host.id)",
163	                kind: .host,
164	                title: host.displayName,
165	                subtitle: hostState?.status.subtitle ?? "\(hostRows.count) sessions",
166	                rows: hostRows,
167	                hostIDs: [host.id],
168	                displayOrderKey: hostRows.first?.displayOrderKey,
169	                newestActivityDate: hostRows.map(\.lastActivityDate).max(),
170	                runningCount: hostRows.filter { $0.status == .running }.count,
171	                isUnavailable: isUnavailable,
172	                unavailableMessage: hostState?.status.unavailableMessage
173	            )
