        switch row.rail {
        case .blue:
            return .blue
        case .green:
            return .green
        case .orange:
            return .orange
        case .red:
            return .red
        case .violet:
            return .purple
        }
    }

    private var statusColor: Color {
        switch row.status {
        case .running:
            return .green
        case .needsInput:
            return .orange
        case .needsApproval:
            return .orange
        case .idle:
            return .blue
        case .error:
            return .red
        case .dormant:
            return .secondary
        case .unknown:
            return .secondary
        }
    }
