            return "Green"
        case .orange:
            return "Orange"
        case .red:
            return "Red"
        case .violet:
            return "Violet"
        }
    }

    var systemImage: String {
        switch self {
        case .blue:
            return "circle.fill"
        case .green:
            return "circle.fill"
        case .orange:
            return "circle.fill"
        case .red:
            return "circle.fill"
        case .violet:
